#include <vector>
using namespace std;

struct Node {
    int val;
    Node *prev, *next;
    Node(int v) : val(v), prev(nullptr), next(nullptr) {}
};

Node *head = nullptr, *tail = nullptr;

void add(int val) {
    Node *New = new Node(val); // Use raw pointers directly for simplicity
    if (!head) {
        head = tail = New;
    } else {
        tail->next = New;
        New->prev = tail;
        tail = New;
    }
}

void del(Node *node) {
    if (node->prev) {
        node->prev->next = node->next;
    } else {
        head = node->next;
    }
    if (node->next) {
        node->next->prev = node->prev;
    } else {
        tail = node->prev;
    }
    delete node; // Deleting the node remains unchanged
}

int main() {
    int N, M, Q;
    scanf("%d %d %d", &N, &M, &Q);
    vector<int> OK(N, 0);
    for (int i = 0; i < N; ++i) add(i);

    Node *cur = head;
    while (M--) {
        int a;
        scanf("%d", &a);
        for (int j = 0; j < a; ++j) {
            cur = (a & 1) ? (cur->prev ? cur->prev : tail) : (cur->next ? cur->next : head);
        }
        Node *tmp = cur;
        cur = cur->next ? cur->next : head;
        del(tmp);
    }

    for (Node *cur = head; cur; cur = cur->next) {
        OK[cur->val] = 1;
    }

    while (Q--) {
        int q;
        scanf("%d", &q);
        printf("%d\n", OK[q]);
    }
}

